public static void main(String[] args) {
    var sc = new Scanner(System.in);
    int n = sc.nextInt();
    int m = sc.nextInt();
    int[] p = new int[n + 1];
    int[] rank = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        p[i] = i;
        rank[i] = 1;
    }
    long ret = 0;
    int mm = m;

    var mp = new HashMap<Integer, Long>();
    var se = new TreeSet<Integer>();
    while (m-- != 0) {
        int x = sc.nextInt();
        int y = sc.nextInt();
        union(x, y, p, rank);
    }

    for (int i = 1; i <= n; i++) {
        int x = find(i, p);
        if (!mp.containsKey(x)) {
            mp.put(x, 0L);
        }
        long t = mp.get(x) + 1;
        mp.put(x, t);
        se.add(x);
    }
    for (int i : se) {
        long tt = mp.get(i);
        long t2 = mp.get(i) - 1;

        ret += tt * t2 / 2;
    }
    ret -= mm;
    System.out.print(ret);
}

private static int find(int x, int[] p) {
    if (p[x] != x) {
        p[x] = find(p[x], p);
    }
    return p[x];
}

private static void union(int x, int y, int[] p, int[] rank) {
    int rootX = find(x, p);
    int rootY = find(y, p);
    if (rootX != rootY) {
        if (rank[rootX] > rank[rootY]) {
            p[rootY] = rootX;
        } else if (rank[rootX] < rank[rootY]) {
            p[rootX] = rootY;
        } else {
            p[rootY] = rootX;
            rank[rootX]++;
        }
    }
}
